      },
    ],
  },
})
.addOperationType(Discord.ApplicationCommandType.ChatInput)
.addBooleanFlag('delete-messages', { name: 'messages', description: 'Delete messages from the banned user.' })
.addNumberFlag('days', { name: 'days', description: 'Number of days to delete messages for.' })
.setActionRow()
.addUserOption({
  name: 'user',
  type: Discord.ChannelType.User,
  description: 'The user to ban.',
  required: true,
})
.bindUserToCommand((binding) => binding.setFlag('delete-messages', binding.command.name === 'ban'));

client.on('interactionCreate', async interaction => {
  if (interaction.commandName === commandName.ban) {
    if (!interaction.guild) return;
    const member = await interaction.guild.members.cache.get(interaction.user.id);
    if (!member) return;

    if (interaction.options.get('delete-messages')) {
      const deleteCount = interaction.options.getFlagNumber('days') * 86400000 + interaction.options.get('days').value;
      await interaction.member.ban({
        reason: `${deleteCount} days`,
