       }

       // Change made on our branch
       if (moreConditions) {
           // Our change
           return thirdValue;
       }
       // (conflict)
       return fourthValue;
       // (green arrow) Indicator for a conflicting line. The line needs to be compared with its counterpart on the other branch to resolve the conflict.
       if (yetAnotherCondition) {
