     System.out.println("str1 and str2 are equal");
   } else {
     System.out.println("str1 and str2 are not equal");
   }
   // The following code can be rewritten with `==` instead:
   if (true == "HelloWorld".equals(str1)) {
      // do something
   } else {
     // This is the equivalent code with the comparison conditions reversed
     System.out.println("str1 and str2 are not equal");
   }
   // If "str1" and "str2" are string literals, as above, then this comparison is also unnecessary,
